use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl AstReflector { pub fn new () -> Self { Self :: default () } pub fn load_probes (& mut self , config_path : & Path) -> Result < () > { let content = fs :: read_to_string (config_path) ? ; self . probes = serde_json :: from_str (& content) ? ; println ! ("🔍 Loaded {} AST probes" , self . probes . len ()) ; Ok (()) } pub fn add_probe (& mut self , probe : AstProbe) { self . probes . push (probe) ; self . probes . sort_by_key (| p | p . priority) ; } pub fn reflect_directory (& mut self , dir : & Path) -> Result < () > { println ! ("🌲 Reflecting AST in directory: {:?}" , dir) ; for entry in walkdir :: WalkDir :: new (dir) { let entry = entry ? ; if entry . file_type () . is_file () && entry . path () . extension () . map_or (false , | ext | ext == "rs") { self . reflect_file (entry . path ()) ? ; } } self . print_summary () ; Ok (()) } pub fn reflect_file (& mut self , file_path : & Path) -> Result < () > { self . current_file = file_path . to_path_buf () ; let content = fs :: read_to_string (file_path) ? ; let mut syntax_tree : File = syn :: parse_str (& content) ? ; self . visit_file_mut (& mut syntax_tree) ; if self . has_transformations () { let transformed = syntax_tree . to_token_stream () . to_string () ; let output_path = self . get_output_path (file_path) ; fs :: create_dir_all (output_path . parent () . unwrap ()) ? ; fs :: write (& output_path , transformed) ? ; println ! ("✨ Transformed: {:?} -> {:?}" , file_path , output_path) ; } Ok (()) } fn has_transformations (& self) -> bool { self . transformation_count . values () . sum :: < usize > () > 0 } fn get_output_path (& self , input_path : & Path) -> PathBuf { let mut output = PathBuf :: from ("ast_reflected") ; output . push (input_path . strip_prefix (".") . unwrap_or (input_path)) ; output } fn create_probe_context (& self , node_name : & str , node_type : AstNodeType , attrs : & [Attribute]) -> ProbeContext { ProbeContext { file_path : self . current_file . clone () , node_name : node_name . to_string () , node_type , attributes : attrs . iter () . map (| a | a . to_token_stream () . to_string ()) . collect () , visibility : "private" . to_string () , complexity : self . calculate_complexity (node_name) , } } fn calculate_complexity (& self , _node_name : & str) -> f64 { use std :: collections :: hash_map :: DefaultHasher ; use std :: hash :: { Hash , Hasher } ; let mut hasher = DefaultHasher :: new () ; _node_name . hash (& mut hasher) ; (hasher . finish () % 100) as f64 / 10.0 } fn apply_probes (& mut self , context : & ProbeContext) -> Vec < TokenStream > { let mut injections = Vec :: new () ; for probe in & self . probes . clone () { if ! probe . enabled { continue ; } if self . matches_filter (& probe . filter , context) { if let Some (injection) = self . execute_probe_action (& probe . action , context) { injections . push (injection) ; * self . transformation_count . entry (probe . name . clone ()) . or_insert (0) += 1 ; } } } injections } fn matches_filter (& self , filter : & ProbeFilter , context : & ProbeContext) -> bool { if let Some (pattern) = & filter . name_pattern { if ! context . node_name . contains (pattern) { return false ; } } if let Some (vis) = & filter . visibility { if context . visibility != * vis { return false ; } } for required_attr in & filter . attributes { if ! context . attributes . iter () . any (| a | a . contains (required_attr)) { return false ; } } if let Some (threshold) = filter . complexity_threshold { if context . complexity < threshold { return false ; } } true } fn execute_probe_action (& mut self , action : & ProbeAction , context : & ProbeContext) -> Option < TokenStream > { match action { ProbeAction :: Log { message } => { println ! ("🔍 [{}] {}: {}" , context . node_type . as_str () , context . node_name , message) ; None } ProbeAction :: AddAttribute { attr } => { let attr_tokens : TokenStream = attr . parse () . ok () ? ; Some (quote ! { # attr_tokens }) } ProbeAction :: WrapFunction { wrapper } => { let wrapper_tokens : TokenStream = format ! ("#[{}]" , wrapper) . parse () . ok () ? ; Some (wrapper_tokens) } ProbeAction :: InjectCode { code , position : _ } => { let code_tokens : TokenStream = code . parse () . ok () ? ; Some (code_tokens) } ProbeAction :: Transform { macro_name , args } => { let transform_code = format ! ("{}!({})" , macro_name , args . join (", ")) ; let code_tokens : TokenStream = transform_code . parse () . ok () ? ; Some (code_tokens) } ProbeAction :: Collect { field } => { self . collected_data . entry (field . clone ()) . or_insert_with (Vec :: new) . push (context . node_name . clone ()) ; None } ProbeAction :: Enhance { enhancement_type , data } => { let enhancement_comment = format ! ("// Enhanced: {} - {}" , enhancement_type , data) ; let tokens : TokenStream = enhancement_comment . parse () . ok () ? ; Some (tokens) } } } fn print_summary (& self) { println ! ("\n📊 AST Reflection Summary:") ; println ! ("========================") ; for (probe_name , count) in & self . transformation_count { println ! ("  🔍 {}: {} transformations" , probe_name , count) ; } if ! self . collected_data . is_empty () { println ! ("\n📋 Collected Data:") ; for (field , values) in & self . collected_data { println ! ("  📊 {}: {} items" , field , values . len ()) ; } } } }